export default function Pedidos() {
  return (
    <div style={{ padding: "2rem", fontSize: "2rem", textAlign: "center" }}>
      <h1>PEDIDOS</h1>
      <p>Aquí irá la lista de pedidos del mesero</p>
      <p style={{ color: "green", marginTop: "2rem" }}>
        ¡YA FUNCIONA! LA PÁGINA DE PEDIDOS CARGA PERFECTO
      </p>
    </div>
  );
}
